-- Física — Mecânica > Cinemática (6 leaves, 5 questões cada)
insert into questions (catalog_node_id, prompt, options, correct_index, explanation, order_index) values
-- Movimento uniforme (8298e55f-972f-4aef-9447-bff9347da0b7)
('8298e55f-972f-4aef-9447-bff9347da0b7', 'Um carro percorre 300 km em 5 horas, mantendo velocidade constante. Qual é a velocidade média do carro?',
  array['60 km/h', '50 km/h', '100 km/h', '1500 km/h'], 0,
  'v = d/t = 300 km / 5 h = 60 km/h.', 1),
('8298e55f-972f-4aef-9447-bff9347da0b7', 'No Movimento Uniforme (MU), a velocidade do móvel é:',
  array['Constante, e a aceleração é nula', 'Sempre crescente', 'Sempre decrescente', 'Variável, mas a aceleração é nula'], 0,
  'No MU, a velocidade permanece constante, portanto a aceleração é zero.', 2),
('8298e55f-972f-4aef-9447-bff9347da0b7', 'Um trem se move a 20 m/s constantes. Qual distância ele percorre em 15 segundos?',
  array['300 m', '150 m', '35 m', '600 m'], 0,
  'd = v × t = 20 × 15 = 300 m.', 3),
('8298e55f-972f-4aef-9447-bff9347da0b7', 'A função horária da posição no Movimento Uniforme é dada por:',
  array['S = S₀ + v·t', 'S = S₀ + v·t + (a·t²)/2', 'S = v²/2a', 'S = S₀ + a·t'], 0,
  'No MU, a posição varia linearmente com o tempo, sem termo de aceleração.', 4),
('8298e55f-972f-4aef-9447-bff9347da0b7', 'Dois carros partem do mesmo ponto, um a 40 km/h e outro a 60 km/h, na mesma direção e sentido. Após 2 horas, qual é a distância entre eles?',
  array['40 km', '20 km', '100 km', '200 km'], 0,
  'A diferença de velocidades é 20 km/h; em 2 horas, a distância entre eles será 20 × 2 = 40 km.', 5),

-- Aceleração (67153ecb-1781-4067-8650-94cb1de96321)
('67153ecb-1781-4067-8650-94cb1de96321', 'Um carro aumenta sua velocidade de 10 m/s para 30 m/s em 4 segundos. Qual é sua aceleração média?',
  array['5 m/s²', '10 m/s²', '20 m/s²', '2,5 m/s²'], 0,
  'a = Δv/Δt = (30-10)/4 = 5 m/s².', 1),
('67153ecb-1781-4067-8650-94cb1de96321', 'A aceleração é uma grandeza física que representa:',
  array['A taxa de variação da velocidade em relação ao tempo', 'A taxa de variação da posição em relação ao tempo', 'A distância total percorrida', 'A força total aplicada sobre um corpo'], 0,
  'A aceleração mede o quanto a velocidade varia por unidade de tempo.', 2),
('67153ecb-1781-4067-8650-94cb1de96321', 'No Sistema Internacional (SI), a unidade de medida da aceleração é:',
  array['m/s²', 'm/s', 'km/h', 'N (newton)'], 0,
  'A aceleração é medida em metros por segundo ao quadrado (m/s²) no SI.', 3),
('67153ecb-1781-4067-8650-94cb1de96321', 'Se um corpo tem aceleração de sinal oposto ao da sua velocidade, isso significa que ele está:',
  array['Reduzindo sua velocidade (desacelerando)', 'Aumentando sua velocidade', 'Em repouso absoluto', 'Com velocidade constante'], 0,
  'Uma aceleração de sinal oposto ao da velocidade indica que o corpo está freando.', 4),
('67153ecb-1781-4067-8650-94cb1de96321', 'Uma moto parte do repouso e atinge 20 m/s em 5 segundos, com aceleração constante. Qual é o valor dessa aceleração?',
  array['4 m/s²', '5 m/s²', '100 m/s²', '15 m/s²'], 0,
  'a = Δv/Δt = (20-0)/5 = 4 m/s².', 5),

-- Movimento uniformemente variado (d8f64aef-8abc-45da-9e5d-501798c0d345)
('d8f64aef-8abc-45da-9e5d-501798c0d345', 'Um carro parte do repouso com aceleração constante de 2 m/s². Qual será sua velocidade após 5 segundos?',
  array['10 m/s', '5 m/s', '2,5 m/s', '25 m/s'], 0,
  'v = v₀ + a·t = 0 + 2×5 = 10 m/s.', 1),
('d8f64aef-8abc-45da-9e5d-501798c0d345', 'No Movimento Uniformemente Variado (MUV), a aceleração é:',
  array['Constante e diferente de zero', 'Sempre igual a zero', 'Variável ao longo do tempo', 'Igual à velocidade'], 0,
  'No MUV, a aceleração é constante (mas não nula), fazendo a velocidade variar uniformemente.', 2),
('d8f64aef-8abc-45da-9e5d-501798c0d345', 'A equação de Torricelli, usada no MUV, relaciona:',
  array['Velocidade final, velocidade inicial, aceleração e deslocamento, sem depender do tempo', 'Apenas velocidade e tempo', 'Apenas posição e tempo', 'Massa e aceleração'], 0,
  'A equação de Torricelli (v² = v₀² + 2·a·Δs) é útil quando o tempo não é conhecido.', 3),
('d8f64aef-8abc-45da-9e5d-501798c0d345', 'Um objeto parte com velocidade inicial de 4 m/s e acelera a 3 m/s² durante 2 segundos. Qual é o deslocamento nesse intervalo, usando S = v₀t + at²/2?',
  array['14 m', '8 m', '6 m', '20 m'], 0,
  'S = v₀·t + (a·t²)/2 = 4×2 + (3×2²)/2 = 8 + 6 = 14 m.', 4),
('d8f64aef-8abc-45da-9e5d-501798c0d345', 'Um veículo com velocidade inicial de 10 m/s freia com aceleração constante de -2 m/s². Qual será sua velocidade após 3 segundos?',
  array['4 m/s', '6 m/s', '16 m/s', '0 m/s'], 0,
  'v = v₀ + a·t = 10 + (-2×3) = 10 - 6 = 4 m/s.', 5),

-- Queda livre (95ca3ad3-5c40-4ccc-b0d0-0c54e2105207)
('95ca3ad3-5c40-4ccc-b0d0-0c54e2105207', 'Na queda livre, desprezando a resistência do ar, a aceleração do corpo é aproximadamente:',
  array['10 m/s² (aceleração da gravidade)', '0 m/s²', '20 m/s²', 'Depende da massa do corpo'], 0,
  'Na queda livre, todo corpo é acelerado pela gravidade, aproximadamente 10 m/s², independentemente da massa.', 1),
('95ca3ad3-5c40-4ccc-b0d0-0c54e2105207', 'Um objeto é abandonado (velocidade inicial zero) e cai em queda livre. Qual será sua velocidade após 3 segundos, considerando g = 10 m/s²?',
  array['30 m/s', '10 m/s', '60 m/s', '13 m/s'], 0,
  'v = g·t = 10 × 3 = 30 m/s.', 2),
('95ca3ad3-5c40-4ccc-b0d0-0c54e2105207', 'Um corpo é abandonado em queda livre e leva 2 segundos para atingir o solo. Qual foi a altura da queda, considerando g = 10 m/s² e h = g·t²/2?',
  array['20 m', '10 m', '40 m', '5 m'], 0,
  'h = (g·t²)/2 = (10×2²)/2 = 20 m.', 3),
('95ca3ad3-5c40-4ccc-b0d0-0c54e2105207', 'Por que, na ausência de resistência do ar, dois corpos de massas diferentes abandonados da mesma altura chegam ao solo ao mesmo tempo?',
  array['Porque a aceleração da gravidade não depende da massa do corpo', 'Porque corpos mais pesados sempre caem mais devagar', 'Porque corpos mais leves sempre caem mais rápido', 'Porque a gravidade varia proporcionalmente à massa'], 0,
  'A aceleração da gravidade é a mesma para todos os corpos, independentemente de sua massa.', 4),
('95ca3ad3-5c40-4ccc-b0d0-0c54e2105207', 'Um objeto é abandonado de uma altura de 45 m. Quanto tempo leva para atingir o solo, considerando g = 10 m/s² e h = g·t²/2?',
  array['3 s', '4,5 s', '9 s', '1,5 s'], 0,
  '45 = (10×t²)/2 → t² = 9 → t = 3 s.', 5),

-- Lançamento horizontal (b6821cec-74b2-4da2-8026-8d821f82f15d)
('b6821cec-74b2-4da2-8026-8d821f82f15d', 'No lançamento horizontal, desprezando a resistência do ar, o movimento pode ser decomposto em:',
  array['Um movimento horizontal uniforme e um movimento vertical de queda livre', 'Dois movimentos uniformemente acelerados na horizontal', 'Um único movimento uniforme em linha reta', 'Um movimento circular uniforme'], 0,
  'O lançamento horizontal combina um MU na horizontal com uma queda livre (MUV) na vertical.', 1),
('b6821cec-74b2-4da2-8026-8d821f82f15d', 'No lançamento horizontal, a componente horizontal da velocidade, durante o voo, permanece:',
  array['Constante', 'Crescente', 'Decrescente', 'Igual a zero'], 0,
  'Como não há força horizontal atuando (desprezando o ar), a velocidade horizontal permanece constante durante todo o trajeto.', 2),
('b6821cec-74b2-4da2-8026-8d821f82f15d', 'Um objeto é lançado horizontalmente de uma altura de 20 m, com velocidade inicial de 10 m/s. Considerando g = 10 m/s², quanto tempo leva para atingir o solo (h = g·t²/2)?',
  array['2 s', '4 s', '1 s', '10 s'], 0,
  '20 = (10×t²)/2 → t² = 4 → t = 2 s. O tempo de queda depende apenas da altura, não da velocidade horizontal.', 3),
('b6821cec-74b2-4da2-8026-8d821f82f15d', 'No exemplo anterior (altura 20 m, velocidade horizontal 10 m/s, tempo de queda 2 s), qual é o alcance horizontal do lançamento?',
  array['20 m', '10 m', '40 m', '200 m'], 0,
  'O alcance horizontal é dado por d = v·t = 10 × 2 = 20 m.', 4),
('b6821cec-74b2-4da2-8026-8d821f82f15d', 'No lançamento horizontal, o tempo total de queda depende:',
  array['Apenas da altura do lançamento e da gravidade', 'Apenas da velocidade horizontal inicial', 'Da massa do objeto lançado', 'Do formato do objeto lançado'], 0,
  'O tempo de queda no lançamento horizontal é determinado exclusivamente pela componente vertical, independente da velocidade horizontal.', 5),

-- Lançamento oblíquo (92e52c60-4571-450a-99cc-e6e840caa2f8)
('92e52c60-4571-450a-99cc-e6e840caa2f8', 'No lançamento oblíquo, desprezando a resistência do ar, a trajetória descrita pelo objeto é:',
  array['Uma parábola', 'Uma reta', 'Um círculo', 'Uma linha ondulada irregular'], 0,
  'A combinação do movimento horizontal uniforme com o movimento vertical acelerado resulta em uma trajetória parabólica.', 1),
('92e52c60-4571-450a-99cc-e6e840caa2f8', 'No ponto mais alto da trajetória de um lançamento oblíquo, a velocidade vertical do objeto é:',
  array['Igual a zero', 'Máxima', 'Igual à velocidade horizontal', 'Negativa'], 0,
  'No ponto mais alto, a velocidade vertical se anula momentaneamente antes de o objeto começar a descer.', 2),
('92e52c60-4571-450a-99cc-e6e840caa2f8', 'No lançamento oblíquo, qual ângulo de lançamento (em relação à horizontal) proporciona o maior alcance horizontal, desprezando a resistência do ar?',
  array['45°', '30°', '60°', '90°'], 0,
  'Para uma mesma velocidade inicial, o ângulo de 45° maximiza o alcance horizontal no lançamento oblíquo.', 3),
('92e52c60-4571-450a-99cc-e6e840caa2f8', 'No lançamento oblíquo, a componente horizontal da velocidade permanece constante durante todo o trajeto porque:',
  array['Não há força horizontal atuando sobre o objeto, desprezando a resistência do ar', 'A gravidade atua igualmente nas duas direções', 'A velocidade vertical também é constante', 'O objeto perde massa durante o voo'], 0,
  'Apenas a gravidade atua sobre o objeto (na vertical), o que mantém a componente horizontal da velocidade constante.', 4),
('92e52c60-4571-450a-99cc-e6e840caa2f8', 'Um projétil é lançado obliquamente e atinge o solo no mesmo nível de onde foi lançado. Comparando o módulo da velocidade de lançamento com o da velocidade de chegada ao solo, desprezando a resistência do ar:',
  array['As duas velocidades têm o mesmo módulo', 'A velocidade de chegada é sempre maior', 'A velocidade de chegada é sempre menor', 'A velocidade de chegada é sempre nula'], 0,
  'Por conservação de energia, ao retornar ao mesmo nível, o módulo da velocidade final é igual ao da velocidade inicial de lançamento.', 5);
